questions.solution:
# 横向条形图（自定义函数 + 字典遍历）
def print_bar(value, max_value, width=10):
    filled = int(value / max_value * width)
    return '#' * filled + '.' * (width - filled)
data = {'A': 8, 'B': 5, 'C': 3}
max_v = max(data.values())
for key, value in data.items():
    print(f'{key}: {print_bar(value, max_v)} ({value})')
